func getTeamMemberInitials(name, email string) string {
	if name != "" {
		runes := []rune(name)
		if len(runes) >= 2 {
			words := splitTeamWords(name)
			if len(words) >= 2 {
				return string([]rune(words[0])[0:1]) + string([]rune(words[len(words)-1])[0:1])
			}
			return string(runes[0:2])
		}
		return string(runes[0:1])
	}
	if email != "" {
		runes := []rune(email)
		if len(runes) >= 2 {
			return string(runes[0:2])
		}
		return string(runes[0:1])
	}
	return "?"
}

func splitTeamWords(s string) []string {
	var words []string
	word := ""
	for _, r := range s {
		if r == ' ' || r == '-' || r == '_' {
			if word != "" {
				words = append(words, word)
				word = ""
			}
		} else {
			word += string(r)
		}
	}
	if word != "" {
		words = append(words, word)
	}
	return words
}

func formatTeamExpiration(t time.Time) string {
	now := time.Now()
	if t.Before(now) {
		return "Expired"
	}
	diff := t.Sub(now)
	if diff < 24*time.Hour {
		return fmt.Sprintf("%.0f hours", diff.Hours())
	}
	days := int(diff.Hours() / 24)
	if days == 1 {
		return "1 day"
	}
	return fmt.Sprintf("%d days", days)
}

